    q(4, '①(2)', '花のつくり', '花の各部分が外側から「がく・花弁・おしべ・めしべ」の順についていることは、花の種類によってちがうか、共通しているか。', T('共通している', '共通', '同じ', 'ちがわない', '共通する'), '教科書p22：この順についているという共通点がある。', tb=22, tbnote='観察2から', near=['ちがう', '種類によってちがう'])
    q(4, '①(3)', 'やく', 'おしべの先端にある小さな袋を何というか。', T('やく', '葯'), '教科書p22：おしべの先端にある小さな袋はやくといい、中には花粉が入っている。', tb=22, tbnote='花のつくりの共通点とちがい', near=['柱頭', '花粉のう'])
    q(4, '①(4)', 'やく', 'やくの中に入っているものは何か。', T('花粉', 'かふん'), '教科書p22：やくの中には花粉が入っている。', tb=22, tbnote='花のつくりの共通点とちがい', near=['胚珠'])
    q(4, '①(5)', '柱頭', 'めしべの先端の部分を何というか。漢字2字で答えよう。', T('柱頭', 'ちゅうとう'), '教科書p22：めしべの先端を柱頭といい、ねばりけがあり、花粉がつきやすくなっている。', tb=22, tbnote='柱頭', near=['花柱', 'やく'])
    q(14, '(1)', '柱頭', '柱頭にねばりけがあると、どのようなよい点があるか。', R((1, ['花粉']), (1, ['つきやす', 'つきやす', 'つく', 'くっつ', '付きやす'])), '教科書p22：柱頭はねばりけがあり、花粉がつきやすくなっている。', tb=22, tbnote='柱頭', example='花粉がつきやすくなる。')
    q(4, '①(5)', '花柱', '柱頭の下の、細くなった部分を何というか。', T('花柱', 'かちゅう'), '教科書p22：柱頭の下の細くなった部分を花柱という。', tb=22, tbnote='花柱', near=['柱頭', '子房'])
    q(4, '①(6)', '子房', 'めしべの根もとの、ふくらんだ部分を何というか。', T('子房', 'しぼう'), '教科書p22：花柱のさらに下のふくらんだ部分を子房という。', tb=22, tbnote='子房', near=['胚珠'])
    q(4, '①(7)', '胚珠', '子房の中にある粒を何というか。', T('胚珠', 'はいしゅ'), '教科書p22：子房の中には胚珠という粒がある。', tb=22, tbnote='胚珠', near=['子房', '種子'])
    q(4, '①(8)', '被子植物', '胚珠が子房の中にある植物を何というか。', T('被子植物', 'ひししょくぶつ'), '教科書p22：胚珠が子房の中にある植物を被子植物という。', tb=22, tbnote='被子植物', near=['裸子植物'])
    q(4, '①(9)', '花のつくりのちがい', 'ふつう1つの花に1つしかないのは、おしべとめしべのどちらか。', T('めしべ', '雌しべ'), '教科書p22：ふつう1つの花にめしべは1つであるが、おしべの数や花弁などは種類によってちがっている。', tb=22, tbnote='本文', near=['おしべ'])
    q(4, '①(9)', '花のつくりのちがい', 'おしべの数や花弁の数は、どの花でも同じか、種類によってちがうか。', T('種類によってちがう', 'ちがう', '種類によって違う', '違う', '異なる'), '教科書p22：おしべの数や花弁などは種類によってちがっている。', tb=22, tbnote='本文', near=['同じ'])
    q(4, '①(1)', '花のつくりのちがい', 'ヘチマのように、雌花と何がある花もあるか。', T('雄花', 'おばな'), '教科書p22図2：ヘチマのように雌花と雄花があるものもある。', tb=22, tbnote='図2 ヘチマとイネの花', near=['雌花'])
    q(4, '①(1)', '花のつくりのちがい', 'イネの花には花弁やがくがない。おしべとめしべは何という殻のようなものでおおわれているか。', T('えい', '穎'), '教科書p22図2：イネのように花弁やがくがなく、おしべとめしべが「えい」という殻のようなものでおおわれた花もある。', tb=22, tbnote='図2 ヘチマとイネの花')
    q(4, '①(1)', '花のつくり', 'アブラナの花のつくりの図（教科書）で、がくの内側の、子房の根もとにある、蜜を出す部分を何と示しているか。', T('蜜腺', 'みつせん'), '教科書p22図1（アブラナの花のつくり）：子房の根もとに蜜腺がある。', tb=22, tbnote='図1 花のつくり')
    q(4, '①(1)', '花粉', '教科書の図で、アブラナやツツジの花粉の大きさは約何mmと示されているか。', N('0.03', ['mm', 'ミリメートル']), '教科書p22〜23：アブラナとツツジの花粉は0.03 mm、エンドウの花粉は0.05 mm。花粉の大きさや形も植物によってちがう。', tb=22, tbnote='図1 花粉', near=['0.05', '0.3'])
    q(4, '①(1)', '花粉', '教科書の図で、エンドウの花粉の大きさは約何mmと示されているか。', N('0.05', ['mm', 'ミリメートル']), '教科書p23：エンドウの花粉は0.05 mm。', tb=23, tbnote='図 エンドウ', near=['0.03', '0.5'])
