    q(4, '①(12)', 'タンポポの花', 'タンポポは、ツツジと同じ合弁花か、アブラナと同じ離弁花か。', T('合弁花', 'ごうべんか', 'ツツジと同じ合弁花'), '教科書p23 Action：タンポポはツツジと同じ合弁花で、小さな1つの花を拡大すると花弁の先端が浅く分かれている。', tb=23, tbnote='図4 タンポポの花', near=['離弁花'])
