    q(5, '②(1)', '花粉の運ばれ方', '教科書の図5で、鳥によって花粉が運ばれる例としてあげられている植物は何か。', T('ツバキ', 'つばき'), '教科書p24図5：ツバキの花に鳥（メジロ）がきている。', tb=24, tbnote='図5 花粉の運ばれ方', near=['アブラナ', 'トウモロコシ'])
